public int CharacterReplacement(string s, int k) {
    var count = new int[26];
    int l = 0, best = 0;
    for (int r = 0; r < s.Length; r++) {
        count[s[r] - 'A']++;
        while (r - l + 1 - count.Max() > k)   // заменить нужно больше k
            count[s[l++] - 'A']--;
        best = Math.Max(best, r - l + 1);
    }
    return best;
}

